<template>
    <!-- 地铁导航 -->
    <div :id="options.id" class="subway-nav-container">
        <scroll>
            <ul class="subway-nav">
                <li class="nav-item" :class="'color' + index%6" v-for="(nav1, index) in navAllList" :key="nav1.id">
                    <div class="nav1" :title="nav1.text" @click="goNavigation(nav1)">
                        {{nav1.text}}
                    </div>
                    <div class="nav2" :class="{active: activeType(nav2.id)}" v-for="nav2 in gainChildrenNavList(nav1)" :key="nav2.id">
                        <div class="nav2-item" @click="chooseTabFn(nav2)">
                            <div class="icon-bg">
                                <div class="icon" :class="{plus: !!nav2.children, minus: activeType(nav2.id)}"></div>
                                <span class="text" :title="nav2.text" @click.stop>{{nav2.text}}</span>
                            </div>
                        </div>
                        <div class="nav3" v-if="activeType(nav2.id)">
                            <div v-for="nav3 in nav2.children" :key="nav3.id" class="nav3-item" @click="chooseTabFn(nav3)">
                                <div class="icon-bg">
                                    <div class="icon"></div>
                                </div>
                                <span class="text" :title="nav3.text">{{nav3.text}}</span>
                            </div>
                        </div>
                    </div>
                </li>
            </ul>
        </scroll>
    </div>
</template>
<script>
    export default {
        name: 'subway-nav',
        props: {
            options: Object
        },

        data() {
            return {
                navAllList: this.options.data,
                openNodeId: [],
            }
        },

        watch: {
            navAllList: {
                handler (newList) {
                    this.navAllList = newList;
                },
                deep: true
            }
        },

        methods: {
            // 点击事件
            chooseTabFn (node) {
                this.goNavigation(node);
                node.children && this.showChildrenNav(node);
            },

            // 跳转 导航
            goNavigation (node) {
                if(!node.href){
                    return;
                }
                // 跳转逻辑
                if (this.options.onClick) {
                    this.options.onClick(node);
                }
            },

            // 是否展开3级导航
            showChildrenNav (node) {
                // 遍历所有id
                let num = this.openNodeId.indexOf(node.id);
                if(num > -1) {
                    this.openNodeId.splice(num, 1);
                } else {
                    this.openNodeId.push(node.id);
                }
            },

            // 获取子导航
            gainChildrenNavList (node) {
                return node.children || [];
            },

            // 监测3级菜单展开的状态
            activeType (id) {
                return this.openNodeId.includes(id);
            }
        }
    }
</script>
